&lt;table CLASS=&quot;tablo&quot;&gt;&lt;caption&gt;Charge transportable &lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;POIDSTRANSPORTABLE&quot; href=&quot;#POIDSTRANSPORTABLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Force&lt;/td&gt;&lt;td&gt;Charge l&#233;g&#232;re&lt;/td&gt;&lt;td&gt;Charge interm&#233;diaire&lt;/td&gt;&lt;td&gt;Charge lourde&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1&lt;/td&gt;&lt;td&gt;jusqu’&#224; 1,5 kg&lt;/td&gt;&lt;td&gt;1,5–3 kg&lt;/td&gt;&lt;td&gt;3–5 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;jusqu’&#224; 3 kg&lt;/td&gt;&lt;td&gt;3–6,5 kg&lt;/td&gt;&lt;td&gt;6,5–10 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;jusqu’&#224; 5 kg&lt;/td&gt;&lt;td&gt;5–10 kg&lt;/td&gt;&lt;td&gt;10–15 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;jusqu’&#224; 6,5 kg&lt;/td&gt;&lt;td&gt;6,5–13 kg&lt;/td&gt;&lt;td&gt;13–20 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;jusqu’&#224; 8 kg&lt;/td&gt;&lt;td&gt;8–16,5 kg&lt;/td&gt;&lt;td&gt;16,5–25 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;jusqu’&#224; 10 kg&lt;/td&gt;&lt;td&gt;10–20 kg&lt;/td&gt;&lt;td&gt;20–30 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;7&lt;/td&gt;&lt;td&gt;jusqu’&#224; 11,5 kg&lt;/td&gt;&lt;td&gt;11,5–23 kg&lt;/td&gt;&lt;td&gt;23–35 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;8&lt;/td&gt;&lt;td&gt;jusqu’&#224; 13 kg&lt;/td&gt;&lt;td&gt;13–26,5 kg&lt;/td&gt;&lt;td&gt;26,5–40 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;9&lt;/td&gt;&lt;td&gt;jusqu’&#224; 15 kg&lt;/td&gt;&lt;td&gt;15–30 kg&lt;/td&gt;&lt;td&gt;30–45 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;10&lt;/td&gt;&lt;td&gt;jusqu’&#224; 16,5 kg&lt;/td&gt;&lt;td&gt;16,5–33 kg&lt;/td&gt;&lt;td&gt;33–50 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11&lt;/td&gt;&lt;td&gt;jusqu’&#224; 19 kg&lt;/td&gt;&lt;td&gt;19–38 kg&lt;/td&gt;&lt;td&gt;38–57,5 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;12&lt;/td&gt;&lt;td&gt;jusqu’&#224; 21,5 kg&lt;/td&gt;&lt;td&gt;21,5–43 kg&lt;/td&gt;&lt;td&gt;43–65 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;13&lt;/td&gt;&lt;td&gt;jusqu’&#224; 25 kg&lt;/td&gt;&lt;td&gt;25–50 kg&lt;/td&gt;&lt;td&gt;50–75 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;14&lt;/td&gt;&lt;td&gt;jusqu’&#224; 29 kg&lt;/td&gt;&lt;td&gt;29–58 kg&lt;/td&gt;&lt;td&gt;58–87,5 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;15&lt;/td&gt;&lt;td&gt;jusqu’&#224; 33 kg&lt;/td&gt;&lt;td&gt;33–66,5 kg&lt;/td&gt;&lt;td&gt;66,5–100 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;16&lt;/td&gt;&lt;td&gt;jusqu’&#224; 38 kg&lt;/td&gt;&lt;td&gt;38–76,5 kg&lt;/td&gt;&lt;td&gt;76,5–115 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;17&lt;/td&gt;&lt;td&gt;jusqu’&#224; 43 kg&lt;/td&gt;&lt;td&gt;43–86,5 kg&lt;/td&gt;&lt;td&gt;86,5–130 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;18&lt;/td&gt;&lt;td&gt;jusqu’&#224; 50 kg&lt;/td&gt;&lt;td&gt;50–100 kg&lt;/td&gt;&lt;td&gt;100–150 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;19&lt;/td&gt;&lt;td&gt;jusqu’&#224; 58 kg&lt;/td&gt;&lt;td&gt;58–116,5 kg&lt;/td&gt;&lt;td&gt;116,5–175 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;20&lt;/td&gt;&lt;td&gt;jusqu’&#224; 66,5 kg&lt;/td&gt;&lt;td&gt;66,5–133 kg&lt;/td&gt;&lt;td&gt;133–200 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;21&lt;/td&gt;&lt;td&gt;jusqu’&#224; 76,5 kg&lt;/td&gt;&lt;td&gt;76,5–153 kg&lt;/td&gt;&lt;td&gt;153–230 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;22&lt;/td&gt;&lt;td&gt;jusqu’&#224; 86,5 kg&lt;/td&gt;&lt;td&gt;86,5–173 kg&lt;/td&gt;&lt;td&gt;173–260 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;23&lt;/td&gt;&lt;td&gt;jusqu’&#224; 100 kg&lt;/td&gt;&lt;td&gt;100–200 kg&lt;/td&gt;&lt;td&gt;200–300 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;24&lt;/td&gt;&lt;td&gt;jusqu’&#224; 116,5 kg&lt;/td&gt;&lt;td&gt;116,5–233 kg&lt;/td&gt;&lt;td&gt;233–350 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;25&lt;/td&gt;&lt;td&gt;jusqu’&#224; 133 kg&lt;/td&gt;&lt;td&gt;133–266,5 kg&lt;/td&gt;&lt;td&gt;266,5–400 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;26&lt;/td&gt;&lt;td&gt;jusqu’&#224; 153 kg&lt;/td&gt;&lt;td&gt;153–306,5 kg&lt;/td&gt;&lt;td&gt;306,5–460 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;27&lt;/td&gt;&lt;td&gt;jusqu’&#224; 173 kg&lt;/td&gt;&lt;td&gt;173–346,5 kg&lt;/td&gt;&lt;td&gt;346,5–520 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;28&lt;/td&gt;&lt;td&gt;jusqu’&#224; 200 kg&lt;/td&gt;&lt;td&gt;200–400 kg&lt;/td&gt;&lt;td&gt;400–600 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;29&lt;/td&gt;&lt;td&gt;jusqu’&#224; 233 kg&lt;/td&gt;&lt;td&gt;233–466,5 kg&lt;/td&gt;&lt;td&gt;466,5–700 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;+10&lt;/td&gt;&lt;td&gt;&#215;4&lt;/td&gt;&lt;td&gt;&#215;4&lt;/td&gt;&lt;td&gt;&#215;4&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Charge est &#233;galement le nom d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;type d&#39;action en combat&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;
Les r&#232;gles qui suivent d&#233;terminent dans quelle mesure le personnage est ralenti par l’armure et la charge qu’il porte. Elles se divisent en deux sections distinctes : le &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;poids de l’armure&lt;/a&gt; et le poids total transport&#233;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Le poids de l’armure.&lt;/b&gt; L’armure que porte le personnage d&#233;termine le bonus maximal de Dext&#233;rit&#233; qu’il peut appliquer &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, son malus d’armure, sa vitesse de d&#233;placement normale et celle qu’il peut esp&#233;rer atteindre en courant (voir le &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;tableau des armures&lt;/a&gt;). &#192; moins que le personnage ne soit tr&#232;s fr&#234;le ou particuli&#232;rement charg&#233;, il n’est pas n&#233;cessaire d’en savoir davantage : en effet, le reste de son &lt;a class=&quot;pagelink&quot; href=&quot;Marchandises-Et-Services.html&quot; title=&quot;&#233;quipement&quot;&gt;&#233;quipement&lt;/a&gt; ne le ralentit pas plus que son &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures.html&quot; title=&quot;Caract&#233;ristiques des armures&quot;&gt;armure&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Par contre, si le personnage est vraiment faible ou si sa charge est exceptionnellement lourde, il faut calculer le poids total de ce qu’il porte. C’est particuli&#232;rement important lorsqu’il d&#233;sire transporter quelque chose de lourd.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Le poids total.&lt;/b&gt; Pour savoir si le poids total port&#233; par un personnage est suffisamment lourd pour le ralentir plus que ne le ferait son armure, il suffit d’additionner le poids de tous les objets qu’il a sur lui : &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;armure&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes.html&quot; title=&quot;Tableau r&#233;capitulatif des armes&quot;&gt;armes&lt;/a&gt; et &#233;quipement (pour l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;aventure&lt;/a&gt;, l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Outils-Alchimiques.html&quot; title=&quot;Outils alchimiques&quot;&gt;alchimie&lt;/a&gt;, d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Outils-De-Comp&#233;tences.html&quot; title=&quot;Outils de comp&#233;tences&quot;&gt;outils&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;V&#234;tements.html&quot; title=&quot;V&#234;tements&quot;&gt;v&#234;tements&lt;/a&gt;). Comparez ensuite ce total avec la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; du personnage sur le tableau ci-dessous. En fonction du r&#233;sultat, cette charge est consid&#233;r&#233;e comme l&#233;g&#232;re, interm&#233;diaire ou lourde. Tout comme l’armure, la charge port&#233;e d&#233;termine le bonus de Dext&#233;rit&#233; maximal applicable &#224; la CA, un malus aux tests (fonctionnant comme le malus d’armure aux tests), la vitesse de d&#233;placement normale du personnage et celle qu’il atteint en courant. Tous ces chiffres sont regroup&#233;s dans le tableau ci-dessous &quot;Effet de la charge&quot;. Une charge lourde ou interm&#233;diaire &#233;quivaut &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Lourdes.html&quot; title=&quot;armure lourde&quot;&gt;armure lourde&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Intermediaires.html&quot; title=&quot;armure interm&#233;diaire&quot;&gt;interm&#233;diaire&lt;/a&gt; en ce qui concerne les activit&#233;s affect&#233;es par le port de l’armure. Une charge l&#233;g&#232;re ne g&#232;ne pas le personnage. Si le personnage porte une armure, on prend seulement en compte le r&#233;sultat le plus &#233;lev&#233; des deux (l’armure ou le poids total), on n’additionne pas les deux.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo&quot;&gt;&lt;caption&gt;Effet de la charge&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td ROWSPAN=&quot;2&quot;&gt;Charge&lt;/td&gt;&lt;td ROWSPAN=&quot;2&quot;&gt;Dex Max&lt;/td&gt;&lt;td ROWSPAN=&quot;2&quot;&gt;Malus aux tests&lt;/td&gt;&lt;td COLSPAN=&quot;2&quot; CLASS=&quot;avecsoustitre&quot;&gt;Vitesse&lt;/td&gt;&lt;td ROWSPAN=&quot;2&quot;&gt;Course&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;soustitre&quot;&gt;&lt;td&gt;(9 m)&lt;/td&gt;&lt;td&gt;(6 m)&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Interm&#233;diaire&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;td&gt;–3&lt;/td&gt;&lt;td&gt;6m&lt;/td&gt;&lt;td&gt;4,50 m&lt;/td&gt;&lt;td&gt;&#215;4&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Lourde&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;td&gt;–6&lt;/td&gt;&lt;td&gt;6m&lt;/td&gt;&lt;td&gt;4,50 m&lt;/td&gt;&lt;td&gt;&#215;3&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Soulever et tirer.&lt;/b&gt; Un personnage peut soulever au-dessus de sa t&#234;te un poids &#233;gal &#224; sa charge maximale, c’est &#224; dire le poids le plus &#233;lev&#233; indiqu&#233; dans la colonne &#171; charge lourde &#187; du tableau ci-dessus (&quot;Charge transportable&quot;) en fonction de la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; du personnage.&lt;br /&gt;&lt;br /&gt;Le personnage peut soulever le double de cette charge maximale mais, dans ce cas, il doit tenir son fardeau &#224; bout de bras et n’avance que difficilement. Il perd tout &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques.html#TABLEAUCARACTERISTIQUES&quot; title=&quot;Les caract&#233;ristiques&quot;&gt;bonus de Dext&#233;rit&#233;&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;vitesse de d&#233;placement&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; passe &#224; 1,50 m&#232;tre par round (ce qui constitue d&#233;sormais pour lui une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;On peut tirer ou pousser jusqu’&#224; cinq fois sa charge maximale autoris&#233;e. Ce chiffre peut &#234;tre doubl&#233; si les conditions sont particuli&#232;rement favorables, ou r&#233;duit de moiti&#233; ou plus si elles sont d&#233;favorables.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Cr&#233;atures plus grandes ou plus petites.&lt;/b&gt; Les chiffres indiqu&#233;s dans le tableau ci-dessus (&quot;Charge transportable&quot;) concernent des bip&#232;des de taille M. Pour des bip&#232;des plus grands, on applique les multiplicateurs suivants, en fonction de leur &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures.html&quot; title=&quot;taille&quot;&gt;taille&lt;/a&gt; : G : &#215;2, TG : &#215;4, Gig : &#215;8 et C : &#215;16. De m&#234;me, les bip&#232;des plus petits transportent un poids moins important qui d&#233;pend aussi de leur cat&#233;gorie de &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures.html&quot; title=&quot;taille&quot;&gt;taille&lt;/a&gt; : P : 3/4, TP : 1/2, Min : 1/4, I : 1/8.&lt;br /&gt;&lt;br /&gt;Les quadrup&#232;des peuvent porter un poids plus important que les bip&#232;des. Multipliez les valeurs donn&#233;es dans le tableau ci-dessus (&quot;Charge transportable&quot;) correspondant &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; des cr&#233;atures par les modificateurs suivants, selon leur &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures.html&quot; title=&quot;taille&quot;&gt;taille&lt;/a&gt; : I : 1/4, Min : 1/2, TP : 3/4, P : 1, M : 3/2, G : &#215;3, TG : &#215;6, Gig : &#215;12 et C : &#215;24.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Force exceptionnelle.&lt;/b&gt; Pour les valeurs de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; d&#233;passant le cadre du tableau ci-dessus (&quot;Charge transportable&quot;), on proc&#232;de de la fa&#231;on suivante : on commence par chercher le nombre compris entre 20 et 29 qui poss&#232;de la m&#234;me unit&#233; que celui de la cr&#233;ature concern&#233;e. Il suffit alors de multiplier ce nombre par 4 pour chaque tranche de 10 points de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; que la cr&#233;ature poss&#232;de au-del&#224; de cette valeur.&lt;br /&gt;&lt;br /&gt;
&lt;h2 class=&quot;separator&quot;&gt; Armure et charge transport&#233;e pour les autres vitesses de d&#233;placement de base &lt;a class=&quot;headeranchor&quot; id=&quot;Armure_et_charge_transport&#233;e_pour_les_autres_vitesses_de_d&#233;placement_de_base_0&quot; href=&quot;#Armure_et_charge_transport&#233;e_pour_les_autres_vitesses_de_d&#233;placement_de_base_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
La table ci-dessous d&#233;voile le malus impos&#233; &#224; toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;vitesse de d&#233;placement&quot;&gt;vitesses de d&#233;placement&lt;/a&gt;, de 1,5 m&#232;tre &#224; 36 m&#232;tres (par tranches de 1,5 m&#232;tres).&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;VD de base&lt;/td&gt;&lt;td&gt;VD r&#233;duite&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;VD de base&lt;/td&gt;&lt;td&gt;VD r&#233;duite&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1,50 m&lt;/td&gt;&lt;td&gt;1,50 m &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;19,50 m&lt;/td&gt;&lt;td&gt;13,50 m&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;3 m - 4,50 m&lt;/td&gt;&lt;td&gt;3 m &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;21 m - 22,50 m&lt;/td&gt;&lt;td&gt;15 m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;6 m&lt;/td&gt;&lt;td&gt;4,50 m&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;24 m&lt;/td&gt;&lt;td&gt;16,50 m&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;7,50 m - 9 m&lt;/td&gt;&lt;td&gt;6 m &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;25,50 m - 27 m&lt;/td&gt;&lt;td&gt;18 m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;10,50 m&lt;/td&gt;&lt;td&gt;7,50 m &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;28,50 m&lt;/td&gt;&lt;td&gt;19,50 m&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;12 m - 13,50 m&lt;/td&gt;&lt;td&gt;9 m &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;30 m - 31,50 m&lt;/td&gt;&lt;td&gt;21 m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;15 m&lt;/td&gt;&lt;td&gt;10,50 m &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;33 m&lt;/td&gt;&lt;td&gt;22,50 m&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;16,50 m - 18 m&lt;/td&gt;&lt;td&gt;12 m&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;34,50 m - 36 m&lt;/td&gt;&lt;td&gt;24 m&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
